WITH remaining_keys AS (SELECT order_id, id FROM payments INTERSECT SELECT order_id, id FROM payments WHERE paid_at < '2025-08-15'), reconciled AS (SELECT s.* FROM payments s JOIN remaining_keys k ON s.order_id = k.order_id AND s.id = k.id) SELECT order_id, CASE WHEN amount >= 1380 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, SUM(amount) FILTER (WHERE method = 'promptpay') AS promptpay_total_amount, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min_2 FROM reconciled GROUP BY order_id, amount_tier
